import java.util.*;

class Solution {
  public int[][] highFive(int[][] items) {
    TreeMap<Integer, PriorityQueue<Integer>> top = new TreeMap<>(); // id -> its 5 best scores (min-heap)
    for (int[] it : items) {
      PriorityQueue<Integer> pq = top.computeIfAbsent(it[0], k -> new PriorityQueue<>());
      pq.add(it[1]);
      if (pq.size() > 5) pq.poll();
    }
    int[][] res = new int[top.size()][];
    int i = 0;
    for (Map.Entry<Integer, PriorityQueue<Integer>> e : top.entrySet()) {
      int sum = 0;
      for (int s : e.getValue()) sum += s;
      res[i++] = new int[] {e.getKey(), sum / 5};
    }
    return res;
  }
}
